package org.ps3.sentinel.core

import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.BeforeClass
import org.junit.Test
import java.io.File
import java.security.MessageDigest
import java.util.Locale

/** DT-14: Kotlin SmsTokenizer vs Python reference ids for bench/bench_messages.txt.
 *
 * Reference file bench/heldout/calib_20261108/token_ids_20261108.jsonl was generated by
 * bench/heldout/dump_probs.py --dump-token-ids: texts = [ln.rstrip("\n") for ln in
 * open(texts_file, encoding="utf-8").read().splitlines() if ln.strip()], then
 * dump_tokens_for_texts enumerates texts with line=index and text_hash=compute_text_hash(text)
 * (sha1 of " ".join(text.strip().lower().split())) and input_ids from _detector_feed_fn, which
 * tokenizes with SmsDetector.tokenizer([text], padding=False if is_dynamic else "max_length",
 * truncation=True, max_length=128) and then remaps through id_map.json. SmsClassifier.predict
 * on Android does the same remap after SmsTokenizer.encode. The Kotlin SmsTokenizer emits
 * pre-remap ids, so this test applies the same id_map before comparing with the reference.
 * The reference is unpadded (dynamic path): [BOS, sequence, EOS] with no pad id 1 and lengths
 * 6..128, 18 at exactly 128 (truncated). Kotlin encode(text, pad = false) has the same shape:
 * BOS + first 126 sequence tokens + EOS.
 *
 * Line mapping: reference "line" equals the index in the filtered texts list. bench_messages.txt
 * has 1000 CRLF-delimited lines with no empty/whitespace-only lines, no leading/trailing spaces
 * and no embedded newline separators, so the splitlines+strip filter is the identity and
 * index == file line number (0-based). This is verified below by count and by text_hash.
 */
class SmsTokenizerBenchParityTest {

    companion object {
        private lateinit var tokenizer: SmsTokenizer
        private lateinit var idMap: IntArray
        private lateinit var messages: List<String>
        private lateinit var refIds: List<List<Long>>
        private lateinit var refHashes: List<String>

        private fun firstExisting(candidates: List<File>): File? =
            candidates.firstOrNull { it.exists() && it.isFile }

        private fun readTextResource(path: String): String? {
            val stream = SmsTokenizerBenchParityTest::class.java.getResourceAsStream(path)
                ?: return null
            return stream.bufferedReader(Charsets.UTF_8).use { it.readText() }
        }

        private fun loadTokenizer(): SmsTokenizer {
            val candidates = listOf(
                File("../../models/sms_v5q/sms_vocab.txt"),
                File("../models/sms_v5q/sms_vocab.txt"),
                File("models/sms_v5q/sms_vocab.txt"),
                File("src/test/resources/sms_vocab.txt"),
                File("app/src/test/resources/sms_vocab.txt")
            )
            val vocabFile = firstExisting(candidates)
            return if (vocabFile != null) {
                SmsTokenizer.fromFile(vocabFile)
            } else {
                val stream = SmsTokenizerBenchParityTest::class.java.getResourceAsStream("/sms_vocab.txt")
                    ?: error("sms_vocab.txt not found in candidate paths or classpath resources")
                SmsTokenizer.fromStream(stream)
            }
        }

        private fun loadIdMap(): IntArray {
            val candidates = listOf(
                File("../../models/sms_v5q/id_map.json"),
                File("../models/sms_v5q/id_map.json"),
                File("models/sms_v5q/id_map.json"),
                File("../../models/sms_v5d/id_map.json"),
                File("../models/sms_v5d/id_map.json"),
                File("models/sms_v5d/id_map.json")
            )
            val file = firstExisting(candidates)
            val jsonText = if (file != null) {
                file.readText(Charsets.UTF_8)
            } else {
                readTextResource("/id_map.json")
                    ?: error("id_map.json not found in candidate paths or classpath resources")
            }
            val arr = JSONArray(jsonText)
            return IntArray(arr.length()) { idx -> arr.getInt(idx) }
        }

        // Mimics dump_probs: open(..., encoding="utf-8").read().splitlines() + strip filter.
        // bench_messages.txt is CRLF-delimited with no other line separators, so splitting the
        // decoded text on "\n" and removing one trailing "\r" yields the same lines Python sees
        // after universal-newline translation + splitlines. The trailing "\n" produces a final
        // empty string which Python splitlines drops; drop it here too.
        private fun splitLikePython(text: String): List<String> {
            var parts = text.split("\n")
            if (parts.isNotEmpty() && parts.last() == "") {
                parts = parts.dropLast(1)
            }
            return parts.map { it.removeSuffix("\r") }
        }

        private fun loadMessages(): List<String> {
            val candidates = listOf(
                File("../../bench/bench_messages.txt"),
                File("../bench/bench_messages.txt"),
                File("bench/bench_messages.txt"),
                File("src/test/resources/bench_messages.txt"),
                File("app/src/test/resources/bench_messages.txt"),
                File("../../android/app/src/test/resources/bench_messages.txt")
            )
            val file = firstExisting(candidates)
            val raw = if (file != null) {
                file.readText(Charsets.UTF_8)
            } else {
                readTextResource("/bench_messages.txt")
                    ?: error("bench_messages.txt not found in candidate paths or classpath resources")
            }
            val lines = splitLikePython(raw)
            return lines.filter { it.trim().isNotEmpty() }
        }

        private fun loadReference(): Pair<List<List<Long>>, List<String>> {
            val candidates = listOf(
                File("src/test/resources/sms_tok_bench_reference.jsonl"),
                File("app/src/test/resources/sms_tok_bench_reference.jsonl"),
                File("android/app/src/test/resources/sms_tok_bench_reference.jsonl"),
                File("../../android/app/src/test/resources/sms_tok_bench_reference.jsonl")
            )
            val file = firstExisting(candidates)
            val raw = if (file != null) {
                file.readText(Charsets.UTF_8)
            } else {
                readTextResource("/sms_tok_bench_reference.jsonl")
                    ?: error("sms_tok_bench_reference.jsonl not found in candidate paths or classpath resources")
            }
            val idsList = mutableListOf<List<Long>>()
            val hashes = mutableListOf<String>()
            var index = 0
            for (line in raw.split("\n")) {
                if (line.isBlank()) continue
                val obj = JSONObject(line)
                assertEquals("reference line field at jsonl row $index", index, obj.getInt("line"))
                val arr = obj.getJSONArray("input_ids")
                idsList.add(List(arr.length()) { idx -> arr.getLong(idx) })
                hashes.add(obj.getString("text_hash"))
                index++
            }
            return idsList to hashes
        }

        @BeforeClass
        @JvmStatic
        fun setUp() {
            tokenizer = loadTokenizer()
            idMap = loadIdMap()
            messages = loadMessages()
            val ref = loadReference()
            refIds = ref.first
            refHashes = ref.second
        }
    }

    private fun computeTextHash(text: String): String {
        if (text.isEmpty()) return ""
        val collapsed = text.trim().lowercase(Locale.ROOT).split(Regex("\\s+")).joinToString(" ")
        val digest = MessageDigest.getInstance("SHA-1").digest(collapsed.toByteArray(Charsets.UTF_8))
        return digest.joinToString("") { "%02x".format(it) }
    }

    private fun remap(ids: LongArray): List<Long> {
        val fallback = idMap[0].toLong()
        return ids.map { orig ->
            if (orig >= 0 && orig < idMap.size) idMap[orig.toInt()].toLong() else fallback
        }
    }

    @Test
    fun testBenchLineMappingAndHash() {
        assertTrue("expected non-empty bench messages", messages.isNotEmpty())
        assertEquals("reference count must equal bench message count", messages.size, refIds.size)
        for (i in messages.indices) {
            assertEquals(
                "text_hash mismatch at bench line $i (mapping or lowercase/split semantics wrong)",
                refHashes[i],
                computeTextHash(messages[i])
            )
        }
        println("Bench parity: compared ${messages.size} messages, hash mapping OK")
    }

    @Test
    fun testBenchParityAgainstPythonReference() {
        val mismatches = mutableListOf<String>()
        for (i in messages.indices) {
            val text = messages[i]
            val actual = remap(tokenizer.encode(text, pad = false).inputIds)
            val expected = refIds[i]
            if (actual != expected) {
                val firstDiff = actual.indices.firstOrNull { idx ->
                    idx >= expected.size || actual[idx] != expected[idx]
                } ?: minOf(actual.size, expected.size)
                mismatches.add(
                    "bench line $i (len expected=${expected.size} actual=${actual.size} " +
                        "firstDiff=$firstDiff): '${text.take(80)}'\n" +
                        "  exp ids: ${expected.take(20)}\n" +
                        "  got ids: ${actual.take(20)}"
                )
            }
        }
        println("Bench parity: ${messages.size - mismatches.size} / ${messages.size} matched, " +
            "${mismatches.size} mismatched")
        if (mismatches.isNotEmpty()) {
            println("Mismatches:\n" + mismatches.take(20).joinToString("\n---\n"))
        }
        assertTrue(
            "Bench tokenizer parity failed: ${mismatches.size} / ${messages.size} mismatched. " +
                "First: ${mismatches.firstOrNull() ?: "none"}",
            mismatches.isEmpty()
        )
    }
}
